#include<bits/stdc++.h>

using namespace std;

class Vehicle{
	private:
		string brand;
		double speed;
	public:
		Vehicle(){
			brand = "";
			speed = 0.0;
		}
		virtual ~Vehicle(){
		}
		void nhap(){
			cout << "Hang san xuat: ";
			cin >> brand;
			cout << "Toc do: ";
			cin >> speed;
		}
		virtual void move(){
			cout << "Di chuyen: ";
		}
		void xuat(){
			cout << "Hang san xuat: " << brand << ", Toc do: " << speed << ", ";
			move();
		}
};

class Car : public Vehicle{
	public:
		void move(){
			Vehicle::move();
			cout << "Dong co.\n";
		}
};

class Bicycle : public Vehicle{
	public:
		void move(){
			Vehicle::move();
			cout << "Suc nguoi.\n";
		}
};

class Motorcycle : public Vehicle{
	public:
		void move(){
			Vehicle::move();
			cout << "Dong co.\n";
		}
};

int main(){
	int n;
	cout << "Nhap n = ";
	cin >> n;
	cout << endl;
	vector<Vehicle*> ds(n);
	for(int i = 0; i < n; i++){
		cout << "Xe thu " << i + 1 << ":\n";
		int loai;
		do {
			cout << "Chon loai (1. Car, 2. Bicycle, 3. Motorcycle): ";
			cin >> loai;
			if (loai == 1) ds[i] = new Car;
			else if (loai == 2) ds[i] = new Bicycle;
			else if (loai == 3) ds[i] = new Motorcycle;
		} while(loai < 1 || loai > 3);
		ds[i]->nhap();
		cout << endl;
	}
	cout << "\n===== DANH SACH XE =====\n";
	for(int i = 0; i < n; i++){
		ds[i]->xuat();
	}
	for(int i = 0; i < n; i++){
		delete ds[i];
	}
	return 0;
}

promptSnapshot.content:
Bạn là giáo viên chấm bài. Hãy chấm bài viết sau dựa trên đề bài và rubric.

Đề bài:
{đề_bài}

Bài làm sinh viên (phần nhập chữ):
{bài_làm}

Phần vẽ tay của sinh viên (đã được bước phân tích hình ảnh đọc trước):
{hình_vẽ}

Lời giải mẫu (nếu có, chỉ dùng để đối chiếu ý, không chép nguyên văn vào feedback):
{lời_giải_mẫu}

Rubric: {rubric}
Điểm tối đa: {max_score}

QUY TẮC CHẤM KẾT HỢP CHỮ + HÌNH VẼ:
- Nếu có cả phần nhập chữ và phần vẽ tay: chấm CẢ HAI theo đề bài/rubric, cho một điểm tổng duy nhất.
- Nếu chỉ có một phần: chỉ chấm phần đó, KHÔNG trừ điểm vì phần sinh viên không nộp.

QUY TẮC PHÁT HIỆN LỖI:
- Chỉ liệt kê lỗi khi lỗi thực sự tồn tại trong bài làm, không tự bịa.
- Nếu đề bài/rubric không đủ căn cứ để xác định một lỗi cụ thể, bỏ qua, không đoán.
- Mỗi lỗi nêu rõ: câu gốc sai, câu đã sửa, giải thích ngắn gọn.

Chỉ trả về JSON hợp lệ, không Markdown, không giải thích ngoài JSON:
{
  "score": number,
  "feedback": string,
  "breakdown": [{ "criterion": string, "score": number, "comment": string }],
  "errors": [{ "original": string, "corrected": string, "explanation": string }]
}
